// Every block, block variant and component example is code an agent copies into a consumer
// app (`webkit add`, the MCP, the docs "Show code"). The consumer lints it with the ESLint
// config `webkit init` writes, so this suite lints all of them with exactly that config —
// generated by the same `eslintFlatConfig` the CLI uses, strict preset — and fails on any
// error. A copied screen must pass the linter it is pasted under.

import { after, before, test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'

import { ESLint } from 'eslint'

import { _internals } from '../../src/cli/plan.js'

const PKG_DIR = fileURLToPath(new URL('../..', import.meta.url))
const PATTERNS = ['blocks/**/*.{vue,ts}', 'examples/**/*.{vue,ts}']
const IMPORTED_PACKAGES = [
  '@aziontech/webkit/eslint-plugin',
  'eslint-plugin-vuejs-accessibility',
  'vue-eslint-parser',
  '@typescript-eslint/parser'
]

// Errors that cannot be fixed in the copied file itself: the component's own spec documents
// the usage the preset rejects. Each entry names where the fix belongs. The last test fails
// once an entry no longer matches anything, so the list only shrinks.
const KNOWN_CONFLICTS = [
  {
    rule: 'webkit/no-style-override',
    tags: ['Spinner'],
    reason:
      'the spec sizes the component through class (Spinner size-*, Carousel.Item w-72, ScrollArea max-h-80, LogView h-full, Sidebar h-screen w-[280px]) or through custom properties (Hero --banner-offset); the spec needs style_seam: true, or the rule needs to accept sizing utilities'
  },
  {
    rule: 'webkit/no-hardcoded-color',
    files: [
      'examples/client-mosaic/site-columns.vue',
      'examples/client-mosaic-columns/default.vue',
      'examples/customer-spotlight/default.vue'
    ],
    reason:
      "the component API takes the client's brand colours as CSS colours (brand: { base, glow }); every spelling of one is a hardcoded colour to the rule"
  },
  {
    rule: 'webkit/no-dropped-children',
    files: [
      'blocks/platform/ai/ai-chat-drawer/ai-chat-drawer.vue',
      'blocks/platform/ai/ai-chat-drawer/variants/error.vue',
      'blocks/platform/ai/ai-chat-drawer/variants/long-thread.vue',
      'blocks/platform/ai/ai-chat-drawer/variants/streaming.vue'
    ],
    reason:
      'the block puts the workload summary straight inside Card, which has no default slot, so it never renders; the fix is to wrap it in <template #content> in the block'
  }
]

function conflictFor(error) {
  return KNOWN_CONFLICTS.find(
    (conflict) =>
      conflict.rule === error.rule &&
      (conflict.files ? conflict.files.includes(error.file) : true) &&
      (conflict.tags ? conflict.tags.some((tag) => error.message.includes(`'<${tag}>'`)) : true)
  )
}

function consumerConfigSource() {
  let source = _internals.eslintFlatConfig('strict')
  for (const specifier of IMPORTED_PACKAGES) {
    const quoted = `'${specifier}'`
    assert.ok(source.includes(quoted), `the init ESLint config no longer imports ${specifier}`)
    source = source.replace(quoted, JSON.stringify(import.meta.resolve(specifier)))
  }
  return source
}

let results = []
let errors = []

before(async () => {
  const previousCatalog = process.env.WEBKIT_CATALOG_PATH
  process.env.WEBKIT_CATALOG_PATH = join(PKG_DIR, 'catalog.json')
  const dir = mkdtempSync(join(tmpdir(), 'webkit-consumer-lint-'))
  try {
    const configFile = join(dir, 'eslint.config.mjs')
    writeFileSync(configFile, consumerConfigSource())
    const eslint = new ESLint({ cwd: PKG_DIR, overrideConfigFile: configFile })
    results = await eslint.lintFiles(PATTERNS)
  } finally {
    rmSync(dir, { recursive: true, force: true })
    if (previousCatalog === undefined) delete process.env.WEBKIT_CATALOG_PATH
    else process.env.WEBKIT_CATALOG_PATH = previousCatalog
  }
  errors = results.flatMap((result) =>
    result.messages
      .filter((message) => message.fatal || message.severity === 2)
      .map((message) => ({
        file: relative(PKG_DIR, result.filePath).split('\\').join('/'),
        line: message.line,
        column: message.column,
        rule: message.ruleId ?? 'parse',
        message: message.message
      }))
  )
})

after(() => {
  results = []
  errors = []
})

test('lints every block, variant and example', () => {
  const vueFiles = results.filter((result) => result.filePath.endsWith('.vue'))
  assert.ok(vueFiles.length > 1000, `expected the blocks and examples, linted ${vueFiles.length}`)
})

test('every block, variant and example passes the ESLint config `webkit init` writes (strict)', () => {
  const unexpected = errors
    .filter((error) => !conflictFor(error))
    .map((error) => `${error.file}:${error.line}:${error.column} ${error.rule} — ${error.message}`)
  assert.deepEqual(
    unexpected,
    [],
    `${unexpected.length} consumer lint error(s):\n${unexpected.join('\n')}`
  )
})

test('every known conflict still occurs, so a fixed one leaves the list', () => {
  const stale = KNOWN_CONFLICTS.flatMap((conflict) => {
    const keys = conflict.files ?? conflict.tags
    return keys
      .filter(
        (key) =>
          !errors.some(
            (error) =>
              conflictFor(error) === conflict &&
              (conflict.files ? error.file === key : error.message.includes(`'<${key}>'`))
          )
      )
      .map((key) => `${conflict.rule} ${key}`)
  })
  assert.deepEqual(stale, [], `remove these from KNOWN_CONFLICTS:\n${stale.join('\n')}`)
})
